const assert = require('node:assert/strict');
const path = require('node:path');
const { chromium } = require(process.env.AGENTNET_PLAYWRIGHT || 'playwright-core');
const [origin, widthText, work, shots] = process.argv.slice(2), width = Number(widthText);
(async () => {
 const browser = await chromium.launch({ executablePath: process.env.AGENTNET_CHROMIUM || '/usr/bin/chromium', headless: true, args: ['--disable-background-networking', '--no-first-run'] });
 try {
  const context = await browser.newContext({ viewport: { width, height: width === 390 ? 844 : 1000 } });
  await context.addCookies([{ name: 'agentnet_ui', value: 'setup-rendered-fixture', url: origin }]);
  const page = await context.newPage(), errors = [], external = [], calls = [];
  await context.route('**/*', r => { if (r.request().url().startsWith(origin + '/')) return r.continue(); external.push(r.request().url()); return r.abort(); });
  page.on('pageerror', e => errors.push(e.message));
  page.on('request', r => { if (new URL(r.url()).pathname.startsWith('/api/')) calls.push({ path: new URL(r.url()).pathname, method: r.method() }); });
  const fit = async () => assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), 'horizontal overflow');
  const shot = async name => { await fit(); await page.screenshot({ path: path.join(shots, `setup-real-${width}-${name}.png`), fullPage: true }); };
  await page.goto(origin + '/fixture'); await page.getByRole('button', { name: 'Set up harnesses', exact: true }).waitFor(); await shot('settings');
  await page.getByRole('button', { name: 'Rename', exact: true }).click();
  await page.getByLabel('Workspace display name', { exact: true }).fill('Mellanni product operations · Inventory and customer experience');
  await shot('workspace-name');
  await page.getByRole('button', { name: 'Save name', exact: true }).click(); await page.locator('.workspace-name-dialog').waitFor({ state: 'detached' });
  assert.equal(await page.getByRole('combobox', { name: 'Active workspace' }).locator('option').first().textContent(), 'Mellanni product operations · Inventory and customer experience');
  await page.getByRole('button', { name: 'Set up harnesses', exact: true }).click();
  await page.getByRole('checkbox', { name: 'Select all detected tools', exact: true }).waitFor();
  await page.keyboard.press('Tab'); // heading was focused; next real control is select-all
  assert.equal(await page.evaluate(() => document.activeElement.getAttribute('aria-label')), 'Select all detected tools');
  assert.equal(await page.evaluate(() => getComputedStyle(document.activeElement).outlineWidth), '3px');
  await page.keyboard.press('Space');
  await page.getByLabel('Codex working folder', { exact: true }).fill(work);
  await page.getByLabel('Claude working folder', { exact: true }).fill(work);
  await page.getByLabel('Pi working folder', { exact: true }).fill(work);
  assert.match(await page.locator('#assistant-setup').innerText(), /OMP supports native hooks and CLI replies only/);
  await shot('choose');
  await page.getByRole('button', { name: 'Review changes', exact: true }).click();
  await page.getByRole('button', { name: 'Confirm setup', exact: true }).waitFor(); await shot('review');
  await page.locator('.setup-review summary').first().click(); await shot('config-details');
  await page.getByRole('button', { name: 'Confirm setup', exact: true }).click();
  await page.getByRole('button', { name: 'Back to settings', exact: true }).waitFor({ timeout: 30000 });
  assert.match(await page.locator('#assistant-setup').innerText(), /public catalog publication confirmed/); await shot('saved');
  await page.getByRole('button', { name: 'Back to settings', exact: true }).click();
  await page.getByRole('button', { name: 'Set up harnesses', exact: true }).click();
  await page.getByLabel('Codex working folder', { exact: true }).waitFor();
  for (const name of ['Codex', 'Claude', 'Pi']) assert.equal(await page.getByLabel(name + ' working folder', { exact: true }).inputValue(), work);
  await page.getByRole('button', { name: 'Review changes', exact: true }).click(); await page.getByRole('button', { name: 'Confirm setup', exact: true }).waitFor();
  assert.match(await page.locator('.setup-review').innerText(), /Reuse assistant/); assert.doesNotMatch(await page.locator('.setup-review').innerText(), /Create assistant/);
  await page.getByRole('button', { name: 'Confirm setup', exact: true }).click(); await page.getByRole('button', { name: 'Back to settings', exact: true }).waitFor({ timeout: 30000 });
  await shot('rerun');
  await page.getByRole('button', { name: 'Back to settings', exact: true }).click();
  await page.getByRole('button', { name: 'Set up harnesses', exact: true }).click(); await page.getByLabel('Codex working folder', { exact: true }).waitFor();
  await page.getByRole('button', { name: 'Review changes', exact: true }).click(); await page.getByRole('button', { name: 'Confirm setup', exact: true }).waitFor();
  const priorCatalog = await (await page.request.get(origin + '/api/agents')).json(), codex = priorCatalog.agents.find(a => a.responder?.harness === 'codex');
  assert((await page.request.post(origin + '/api/agents', { headers: { Origin: origin }, data: { action: 'disable', id: codex.record.id } })).ok());
  await page.getByRole('button', { name: 'Confirm setup', exact: true }).click();
  await page.getByRole('alert').filter({ hasText: /selected assistant changed or was disabled/ }).waitFor(); await shot('stale-assistant');
  const refusedCatalog = await (await page.request.get(origin + '/api/agents')).json(); assert.equal(refusedCatalog.agents.length, 3); assert.equal(refusedCatalog.agents.find(a => a.record.id === codex.record.id).enabled, false);
  assert((await page.request.post(origin + '/api/agents', { headers: { Origin: origin }, data: { action: 'update', id: codex.record.id, harness: 'codex', dir: work } })).ok());
  const creates = calls.filter(c => c.path === '/api/agents' && c.method === 'POST'); assert(creates.length >= 3, 'named assistant API was not used');
  const beforeBrowser = calls.length;
  await page.goto(origin + '/fixture?browser=1'); await page.getByText(/This browser cannot inspect or install software/).waitFor(); await shot('browser');
  assert.equal(calls.length, beforeBrowser, 'browser-only setup called native API');
  assert.deepEqual(errors, []); assert.deepEqual(external, []);
  console.log(JSON.stringify({ width, realNativeAPI: true, catalogBridge: true, rerunReusesRecords: true, OMPManagedUnavailable: true, keyboardFocus: true, configurationDetails: true, staleAssistantFailsClosed: true, nativeWorkspaceRename: true, browserCallsNativeAPI: false, horizontalOverflow: false, pageErrors: errors, externalRequests: external }));
 } finally { await browser.close(); }
})().catch(e => { console.error(e); process.exitCode = 1; });
